import type { InputValue } from '../runtime.js';


export type PayoutsListInput = { /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency"?: InputValue<string>; "method"?: InputValue<"standard">; "balance_source_type"?: InputValue<"card" | "bank_account" | "fpx">; "payout_destination_id"?: InputValue<string>; /** minLength: 1. maxLength: 255. */ "external_reference_id"?: InputValue<string>; "query"?: InputValue<string>; "status"?: InputValue<"pending" | "in_transit" | "paid" | "failed" | "canceled">; /** Format: date-time. */ "created_after"?: InputValue<string | globalThis.Date>; /** Format: date-time. */ "created_before"?: InputValue<string | globalThis.Date>; /** Format: date-time. */ "arrival_after"?: InputValue<string | globalThis.Date>; /** Format: date-time. */ "arrival_before"?: InputValue<string | globalThis.Date>; /** minimum: 1. maximum: 100. */ "page_size"?: InputValue<number>; "page_token"?: InputValue<string>; "X-Request-Id"?: InputValue<string>; /** Format: date. */ "Flint-Version"?: InputValue<string>; };
